{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Eravacycline, the query molecule, had an absolute oral bioavailability of 28% (range 26–32%) in healthy subjects across 50–300 mg oral solution doses compared with IV, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Omadacycline, a structurally related aminomethylcycline, has an absolute oral bioavailability of 34.5% in humans (300 mg oral vs 100 mg IV), supporting moderate oral bioavailability in this tetracycline class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Minocycline, a tetracycline scaffold analogue, exhibits 90–100% oral bioavailability in humans, supporting generally good oral absorption for the tetracycline class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Tigecycline, a close structural analogue, has low oral bioavailability and is administered IV only in humans, providing a contradictory direction but with lower transferability because direct eravacycline human data show 28% oral bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct human absolute bioavailability data for eravacycline show 28% (range 26–32%), clearly above the 20% threshold. Related tetracycline/fluorocycline analogues mostly support moderate-to-high oral bioavailability, while tigecycline's low oral bioavailability is outweighed by the direct eravacycline measurement.",
  "evidence_gaps": [
    "No material evidence gap: direct human absolute bioavailability data exist for the query molecule. Minor uncertainties include formulation and food effects, but the reported 28% value is clearly above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

